-- =====================================================================
-- Etapa A — carga de la FOTO de precios de LIGE (abril 2026) en objetivo_precios.
-- Fuente: Base Precios LIGE.xlsx. Una fila por objetivo de sucursales (474).
-- Cruce por codigo_objetivo. precio_hora = Importe Hora A (vacio -> 0);
-- precio_hora_b = Importe Hora B tal cual (null si vacio). tipo='real' (abril cerrado).
-- tipo_precio: >20000 -> 'fijo', si no 'hora'. tipo_servicio de sucursales. fuente='lige'.
-- Objetivos internos (precio 0, tipo Lince) se cargan igual con precio_hora=0.
-- Idempotente: on conflict (sucursal_id, mes, tipo_servicio) DO NOTHING.
-- Sin begin/commit.
-- =====================================================================

-- PREVIA: objetivo_precios vacia (esperado 0)
select count(*) as filas_antes from public.objetivo_precios;

on conflict (sucursal_id, mes, tipo_servicio) do nothing;

-- POSTERIOR 1: total cargado (esperado 474)
select count(*) as filas_despues from public.objetivo_precios;
-- POSTERIOR 2: por tipo_precio (esperado hora 466, fijo 8)
select tipo_precio, count(*) from public.objetivo_precios group by tipo_precio order by tipo_precio;
-- POSTERIOR 3: cuantos en precio_hora=0 (internos, esperado 64)
select count(*) as precio_cero from public.objetivo_precios where precio_hora = 0;
-- POSTERIOR 4: muestra de 10 variadas
select codigo_objetivo, cliente_id, precio_hora, precio_hora_b, tipo_precio, tipo_servicio
  from public.objetivo_precios order by precio_hora desc limit 5;
select codigo_objetivo, cliente_id, precio_hora, precio_hora_b, tipo_precio, tipo_servicio
  from public.objetivo_precios where precio_hora between 1 and 20000 order by precio_hora limit 5;
-- POSTERIOR 5: los objetivos con precio_hora=0 (revisar despues)
select codigo_objetivo, precio_hora, tipo_servicio
  from public.objetivo_precios where precio_hora = 0 order by codigo_objetivo;
